{
  "a_sentences": [
    {
      "a_text": "Lorsque le bail est de durée indéterminée, chaque partie peut le résilier pour la prochaine échéance en respectant le délai de congé prévu.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Le bailleur est libre de résilier le bail notamment pour utiliser les locaux lui-même ou pour ses proches parents ou alliés.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "La résiliation ordinaire du bail est annulable si elle contrevient aux règles de la bonne foi, sauf disproportion crasse des intérêts.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Le congé-représailles est d'autant plus vraisemblable qu'il survient rapidement après que le locataire a élevé une prétention.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "La réglementation des art. 271 et 271a CO protège uniquement le locataire contre des résiliations abusives.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Pour statuer sur la validité du congé, il faut examiner l'intérêt du bailleur à récupérer son bien, sans peser cet intérêt contre celui du locataire à rester dans les locaux.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "La juridiction cantonale a retenu que la volonté de l'intimée était de vendre l'appartement litigieux.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le Tribunal fédéral confirme que, sur la base des faits retenus sans arbitraire, il n'existe aucune disproportion crasse entre l'intérêt de la personne assurée à demeurer dans l'appartement et celui de l'assureur à pouvoir vendre son bien libre de tout occupant.",
      "b_propositions": ["P8"]
    }
  ]
}
